#!/usr/bin/env bash
# Run all cases generated by generate.py, N_JOBS simulations in parallel (one OpenMP thread each).
# Interrupted simulations are continued from their last restart point.
# Usage: ./run_all.sh [runs directory] [file with case names (default: all cases)]
set -u
RUNS=$(realpath "${1:-$(dirname "$0")/runs}")
N_JOBS=${N_JOBS:-4}
export DAMASK_GRID=${DAMASK_GRID:-damask_grid}
export PYTHON=${PYTHON:-python3}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-1}

run() {
  cd "$1" || exit 1
  [ -f job.done ] && exit 0
  restart=""
  if [ -f job_restart.hdf5 ]; then
    inc=$("$PYTHON" - <<'PY' 2>/dev/null
import h5py
inc = int(h5py.File('job_restart.hdf5','r').attrs['increment'])
with h5py.File('job.hdf5','a') as f:                                # drop results written after the restart point
    for k in [k for k in f if k.startswith('increment_') and int(k.split('_')[1]) > inc]:
        del f[k]
print(inc)
PY
) && restart="-r $inc"
  fi
  "$DAMASK_GRID" -l load.yaml -g geom.vti -m material.yaml -n numerics.yaml -j job $restart >> log.txt 2>&1 \
    && touch job.done || echo "FAILED: $1"
}
export -f run

if [ $# -ge 2 ]; then cases=$(sed "s|^|$RUNS/|" "$2"); else cases=$(ls -d "$RUNS"/*/); fi
printf '%s\n' $cases | xargs -P "$N_JOBS" -I{} bash -c 'run {}'
